const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=s=>{try{const u=new URL(s);return /^https?:$/.test(u.protocol)?u.href:''}catch{return ''}};
const $=s=>document.querySelector(s);const key='folio-library-v1';
const seeds=createStarterLibrary().papers;
const phoneMedia=window.matchMedia?.('(max-width: 600px)');
const isPhone=()=>phoneMedia?.matches===true;
const remoteMode=window.FOLIO_REMOTE===true;let csrf='',revision=0,confirmed=null,saving=false,currentUser=null,accountEpoch=0,aiConfigured=false,classifying=false,classificationSequence=0,lastClassification='';
let papers=[];let settings={};try{papers=JSON.parse(localStorage.getItem(key)||'null')||seeds;settings=JSON.parse(localStorage.getItem('folio-settings')||'{}')}catch{papers=seeds}
function citationOnly(p){const {pdfId,drivePdfId,pdfName,hasPdf,needsPdfUpload,...citation}=p;return {...citation,importance:normalizeImportance(citation.importance)}}
function citationSettings(s){return {collections:s.collections||[],...(s.autoCollections!==undefined?{autoCollections:s.autoCollections===true}:{}),...(s.autoCreateCollections!==undefined?{autoCreateCollections:s.autoCreateCollections!==false}:{}),...(s.collectionInstructions!==undefined?{collectionInstructions:String(s.collectionInstructions).slice(0,1000)}:{})}}
papers=papers.map(citationOnly);settings=citationSettings(settings);if(remoteMode){papers=[];settings={}}
let view='library',collection='',extraCollections=[],collectionMatch='any',query='',statusFilter='all',priorityFilter='all',sort='newest',layout='grid',recommendations=[],discoverState='';
function enrichVenue(p){if(!p.rank && p.venue==='IEEE Symposium on Security and Privacy')Object.assign(p,{rank:'A*',metricType:'CORE rank',metricYear:'2023',metricSource:'https://portal.core.edu.au/conf-ranks/?by=all&search=security&source=CORE2023'});return p}
papers.forEach(enrichVenue);
const labels={library:'All papers',queue:'Reading queue',favorites:'Important papers',discover:'Discover',settings:'Settings & storage'};
function rememberCollections(tags){const all=parseTags([...(settings.collections||[]),...tags].join(', '));if(all.length<=1000)settings.collections=all}
async function save(){if(settings.autoCollections)rememberCollections(papers.flatMap(p=>p.tags||[]));papers=papers.map(citationOnly);settings=citationSettings(settings);if(remoteMode){await persistRemote()}else{localStorage.setItem(key,JSON.stringify(papers));updateSidebar()}}
async function saveSettings(){settings=citationSettings(settings);if(remoteMode){await persistRemote()}else localStorage.setItem('folio-settings',JSON.stringify(settings))}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function hydrate(){document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon))}
function activeCollections(){return collection?[collection,...extraCollections]:[]}
function collectionSelected(path){return path?activeCollections().some(t=>t.toLowerCase()===path.toLowerCase()):!collection}
function collectionLabel(){const tags=activeCollections();return tags.length>1?tags.length+' collections':tags[0]||''}
function collectionHash(){const tags=activeCollections();if(!tags.length)return view;if(tags.length===1&&view==='library'&&collectionMatch==='any')return 'collection='+encodeURIComponent(tags[0]);return 'collections='+encodeURIComponent(JSON.stringify(tags))+'&view='+view+'&match='+collectionMatch}
function setCollectionFilters(tags,sync=true){const unique=new Map();for(const tag of tags){if(typeof tag!=='string'||!tag||tag.length>200)continue;const path=normalizeCollection(tag);if(path&&!unique.has(path.toLowerCase()))unique.set(path.toLowerCase(),path)}const paths=[...unique.values()].slice(0,100);collection=paths[0]||'';extraCollections=paths.slice(1);if(!paths.length)collectionMatch='any';if(sync)location.hash=collectionHash()}
function toggleCollection(path){if(!['library','queue','favorites'].includes(view)){view='library';query='';statusFilter='all';priorityFilter='all'}if(!path)setCollectionFilters([]);else{const tags=activeCollections();setCollectionFilters(collectionSelected(path)?tags.filter(t=>t.toLowerCase()!==path.toLowerCase()):[...tags,path])}render()}
function parseCollectionHash(hash){try{if(hash.startsWith('collection='))return {view:'library',tags:[decodeURIComponent(hash.slice(11))],match:'any'};if(hash.startsWith('collections=')){const params=new URLSearchParams(hash),tags=JSON.parse(params.get('collections'));if(!Array.isArray(tags)||tags.length>100||tags.some(t=>typeof t!=='string'||!t||t.length>200))throw new Error('Invalid filter');const next=params.get('view');return {view:['library','queue','favorites'].includes(next)?next:'library',tags,match:params.get('match')==='all'?'all':'any'}}}catch{}return {view:labels[hash]?hash:'library',tags:[],match:'any'}}
function restoreCollectionHash(hash){const next=parseCollectionHash(hash);if(next.view===view&&JSON.stringify(next.tags)===JSON.stringify(activeCollections())&&next.match===collectionMatch)return false;view=next.view;collectionMatch=next.match;setCollectionFilters(next.tags,false);query='';statusFilter='all';priorityFilter='all';return true}
function collectionFilterButton(){const tags=activeCollections(),text=tags.length===1?tags[0].replaceAll('/',' › '):tags.length?tags.length+' collections':'All collections';return `<button type="button" class="collection-filter-button ${tags.length?'active':''}" data-choose-collections aria-haspopup="dialog" aria-label="Filter collections: ${esc(text)}" title="${esc(text)}"><span>${esc(text)}</span><span aria-hidden="true">⌄</span></button>`}
function chooseCollections(){
 const draft=new Set(activeCollections()),tags=collectionTree();let match=collectionMatch;
 modal(modalTitle('Filter collections.')+`<div class="collection-picker"><div class="field"><label for="collection-picker-search">Find a collection</label><input type="search" id="collection-picker-search" placeholder="Search collections…"></div><div class="collection-picker-options"><label>Match<select id="collection-picker-match"><option value="any">Any selected collection</option><option value="all">All selected collections</option></select></label><button type="button" class="button" id="collection-picker-clear">Clear selection</button></div><div id="collection-picker-tree" class="collection-picker-tree"></div><p id="collection-picker-count" class="collection-help" role="status"></p><div class="modal-actions"><button type="button" class="button" data-manage-collections>Manage collections</button><button type="button" class="button" data-close>Cancel</button><button type="button" class="button primary" id="collection-picker-apply">Apply filters</button></div></div>`);
 const paint=()=>{const term=$('#collection-picker-search').value.trim().toLowerCase(),matches=tags.filter(t=>t.path.toLowerCase().includes(term)),visible=term?tags.filter(t=>matches.some(m=>m.path===t.path||m.path.startsWith(t.path+'/'))):tags;$('#collection-picker-tree').innerHTML=visible.length?visible.map(t=>`<label class="collection-picker-row" style="--collection-depth:${t.depth}" title="${esc(t.path)}"><input type="checkbox" data-pick-collection="${esc(t.path)}" ${draft.has(t.path)?'checked':''}><span>${esc(t.label)}</span><small>${collectionCount(t.path)}</small></label>`).join(''):'<p class="collection-help">'+(tags.length?'No matching collections.':'No collections yet. Use Manage collections to create one.')+'</p>';$('#collection-picker-count').textContent=draft.size?draft.size+' selected · Includes child collections':'All collections';$('#collection-picker-match').disabled=!draft.size};
 $('#collection-picker-search').value='';$('#collection-picker-search').oninput=paint;
 $('#collection-picker-match').value=match;$('#collection-picker-match').onchange=e=>{match=e.target.value==='all'?'all':'any'};
 $('#collection-picker-tree').onchange=e=>{const path=e.target.dataset.pickCollection;if(!path)return;if(e.target.checked)draft.add(path);else draft.delete(path);$('#collection-picker-count').textContent=draft.size?draft.size+' selected · Includes child collections':'All collections';$('#collection-picker-match').disabled=!draft.size};
 $('#collection-picker-clear').onclick=()=>{draft.clear();paint()};
 $('#collection-picker-apply').onclick=()=>{collectionMatch=match;setCollectionFilters([...draft]);close();render()};paint();
}
function updateSidebar(){ if(remoteMode){$('#workspace-name').textContent=currentUser?currentUser.username+'’s library':'Sign in to Folio';$('#profile-name').textContent=currentUser?.username||'Signed out';} $('#nav-total').textContent=papers.length;$('#nav-unread').textContent=papers.filter(p=>p.status==='unread').length;$('#collections').innerHTML=collectionTree().map(t=>`<button class="collection ${collectionSelected(t.path)?'active':''}" style="padding-left:${15+t.depth*14}px" data-collection="${esc(t.path)}" aria-pressed="${collectionSelected(t.path)}" title="${esc(t.path)}"><i></i>${esc(t.label)}<span>${collectionCount(t.path)}</span></button>`).join('');document.querySelectorAll('[data-view]').forEach(b=>{const active=b.dataset.view===view;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')}); }
function navigate(next,tag=''){view=next;collectionMatch='any';setCollectionFilters(tag?[tag]:[],false);query='';statusFilter='all';priorityFilter='all';location.hash=collectionHash();render();if(isPhone())$('.main-shell')?.scrollTo?.({top:0})}
function heading(title,description,actions=true){return `<div class="page-heading"><div><div class="eyebrow">YOUR PERSONAL RESEARCH SPACE</div><h1>${esc(title)}</h1><p>${description}</p></div>${actions?`<div class="heading-actions"><button class="button" id="export-library">${icon('download')}<span class="export-text">Export citations</span></button><button class="button primary" id="add-paper">${icon('plus')}Add paper</button></div>`:''}</div>`}
function importanceOptions(){return [5,4,3,2,1,0].map(n=>`<option value="${n}">${n} ${n===1?'star':'stars'}</option>`).join('')}
function ratingStars(value,attributes,title=''){
 const rating=normalizeImportance(value),label=title?' for '+title:'';
 return `<span class="importance-stars" role="group" aria-label="Importance${esc(label)}: ${rating} of 5 stars">${[1,2,3,4,5].map(n=>`<button type="button" class="rating-star ${n<=rating?'filled':''}" ${attributes} data-rating-value="${n}" aria-label="Set ${n} ${n===1?'star':'stars'}${esc(label)}" aria-pressed="${n===rating}" title="${n} of 5 stars">${n<=rating?'★':'☆'}</button>`).join('')}<button type="button" class="rating-zero" ${attributes} data-rating-value="0" aria-label="Set 0 stars${esc(label)}" aria-pressed="${rating===0}" title="Clear importance (0 stars)">0</button></span>`;
}
function ratingField(id,value=3){return `<div class="field"><span id="${id}-label">Importance</span><input type="hidden" id="${id}" value="${normalizeImportance(value)}"><div class="rating-field" id="${id}-stars" aria-labelledby="${id}-label">${ratingStars(value,'data-rating-input="'+id+'"')}</div></div>`}
function readRating(id){const value=$('#'+id).value;return normalizeImportance(/^[0-5]$/.test(String(value))?Number(value):value)}
function card(p,external=false){const metric=p.rank?`${esc(p.metricType||'Rank')} ${esc(p.rank)} · ${esc(p.metricYear||'')}`:'Venue metrics not recorded';return `<article class="paper-card"><div class="card-top"><span class="badge ${p.status}"><i></i>${external?'DISCOVERED':p.status==='read'?'Read':p.status==='reading'?'Reading':'Unread'}</span>${external?`<button class="star-button" data-import="${esc(p.id)}" title="Add to library" aria-label="Add ${esc(p.title)} to library">+</button>`:ratingStars(p.importance,'data-rate-paper="'+esc(p.id)+'"',p.title)}</div><button class="paper-title" ${external?'data-external':'data-paper'}="${esc(p.id)}">${esc(p.title)}</button><div class="authors">${esc(p.authors||'Authors not recorded')}</div><div class="tags">${(p.tags||[]).slice(0,3).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="card-bottom"><span class="venue" title="${esc(p.venue)}">${icon('venue')}${esc(p.venue||'Venue not recorded')}</span><span class="paper-year">${icon('link')}${esc(p.year||'—')}</span></div><div class="metric-line">${metric}</div></article>`}
function filtered(){let list=papers.filter(p=>(view!=='queue'||p.status==='unread')&&(view!=='favorites'||normalizeImportance(p.importance)>=4)&&(!collection||(collectionMatch==='all'?activeCollections().every(t=>inCollection(p.tags,t)):activeCollections().some(t=>inCollection(p.tags,t))))&&(statusFilter==='all'||p.status===statusFilter)&&(priorityFilter==='all'||normalizeImportance(p.importance)===normalizeImportance(/^[0-5]$/.test(priorityFilter)?Number(priorityFilter):priorityFilter))&&`${p.title} ${p.authors} ${p.venue} ${p.tags.join(' ')}`.toLowerCase().includes(query.toLowerCase()));return list.sort((a,b)=>sort==='oldest'?a.added-b.added:sort==='year'?(b.year||0)-(a.year||0):sort==='title'?a.title.localeCompare(b.title):sort==='importance'?(normalizeImportance(b.importance)-normalizeImportance(a.importance))||b.added-a.added:b.added-a.added)}
function renderPapers(){const list=filtered();$('#paper-results').innerHTML=list.length?list.map(p=>card(p)).join(''):`<div class="empty">${icon('book')}<h3>A little room for discovery.</h3><p>${papers.length?'No papers match these filters.':'Add your first paper to begin your library.'}</p><button class="button" id="empty-add">${icon('plus')}Add a paper</button></div>`;$('#result-count').textContent=`${list.length} ${list.length===1?'paper':'papers'}`;}
function render(){if(remoteMode&&!confirmed){showLogin();return}updateSidebar();$('#breadcrumb').textContent=collectionLabel()||labels[view];if(view==='settings'){renderSettings();return}if(view==='discover'){renderDiscover();return}if(isPhone()){renderPhoneLibrary();return}const unread=papers.filter(p=>p.status==='unread').length;const title=collectionLabel()||labels[view];$('#main').innerHTML=heading(title,view==='queue'?'Turn your reading list into your next great idea.':view==='favorites'?'The papers you want to keep close.':'A home for the ideas that move your research forward.')+`<section class="hero"><div class="hero-content"><div class="eyebrow">${icon('spark')} A LITTLE DIRECTION FOR YOUR NEXT READ</div><h2>${view==='queue'?'Good research starts with one paper.':'Your next idea is waiting in your library.'}</h2><p>${unread?`You have ${unread} unread papers. Let’s find a good place to start.`:'Your reading queue is clear. Discover something new to explore.'}</p><button class="button" id="pick-paper">${icon('book')}${unread?'Pick my next read':'Discover papers'} ${icon('arrow')}</button>${view==='queue'?'<div class="queue-options"><label><input id="prefer-important" type="checkbox" checked> Prefer important papers</label><label><input id="random-pick" type="checkbox"> Surprise me</label></div>':''}</div><div class="hero-art" aria-hidden="true"><div class="art-ring"></div><div class="art-ring second"></div><div class="book-cover"></div><div class="book-front"><small>COLLECTED IDEAS</small><em>A world<br>of possibility.</em><div class="lines"></div></div><span class="spark">✦</span></div></section><div class="stats">${[[papers.length,'Total papers','library'],[unread,'Waiting to be read','clock'],[papers.filter(p=>p.status==='read').length,'Papers read','check'],[papers.filter(p=>normalizeImportance(p.importance)>=4).length,'Important papers','star']].map(([n,l,i])=>`<div class="stat"><span class="stat-icon">${icon(i)}</span><div><strong>${n}</strong><small>${l}</small></div></div>`).join('')}</div><div class="section-title"><h2>${esc(collectionLabel()|| (view==='queue'?'Your unread papers':view==='favorites'?'Your important papers':'Your library'))}<span id="result-count"></span></h2><span class="subtle-link">Small steps. New perspectives.</span></div><div class="toolbar"><label class="search">${icon('search')}<input id="search" placeholder="Search by title, author, or keyword…" aria-label="Search papers" value="${esc(query)}"></label>${collectionFilterButton()}<select id="status-filter" aria-label="Filter reading status"><option value="all">All statuses</option><option value="unread">Unread</option><option value="reading">Reading</option><option value="read">Read</option></select><select id="priority-filter" aria-label="Filter importance"><option value="all">All importance</option>${importanceOptions()}</select><select id="sort" aria-label="Sort papers"><option value="newest">Newest added</option><option value="oldest">Oldest added</option><option value="year">Publication year</option><option value="title">Title A–Z</option><option value="importance">Importance</option></select><div class="view-toggle"><button data-layout="grid" class="${layout==='grid'?'selected':''}" aria-label="Grid view">${icon('grid')}</button><button data-layout="list" class="${layout==='list'?'selected':''}" aria-label="List view">${icon('list')}</button></div></div><div class="paper-grid ${layout==='list'?'list':''}" id="paper-results"></div>${papers.some(p=>p.sample)?'<div class="sample-note"><span>Explore with a sample library. Your own papers belong here, too.</span><button id="remove-samples">Remove sample papers</button></div>':''}`;renderPapers();$('#status-filter').value=statusFilter;$('#priority-filter').value=priorityFilter;$('#sort').value=sort;$('#search').oninput=e=>{query=e.target.value;renderPapers()};['status','priority'].forEach(type=>$('#'+type+'-filter').onchange=e=>{if(type==='status')statusFilter=e.target.value;else priorityFilter=e.target.value;renderPapers()});$('#sort').onchange=e=>{sort=e.target.value;renderPapers()};}
function modal(html){classificationSequence++;classifying=false;lastClassification='';$('#modal-content').innerHTML=`<div class="modal-inner">${html}</div>`;if(!$('#modal').open)$('#modal').showModal()}
function close(){classificationSequence++;classifying=false;lastClassification='';$('#modal').close()}
function modalTitle(title){return `<div class="modal-header"><h2>${esc(title)}</h2><button class="close" data-close aria-label="Close dialog">×</button></div>`}
function normalizeCollection(value){return String(value).split('/').map(s=>s.trim()).filter(Boolean).join('/')}
function inCollection(tags,path){return (tags||[]).some(t=>t.toLowerCase()===path.toLowerCase()||t.toLowerCase().startsWith(path.toLowerCase()+'/'))}
function collectionCount(path){return papers.filter(p=>inCollection(p.tags,path)).length}
function collectionTree(){const roots=new Map();for(const value of [...(settings.collections||[]),...papers.flatMap(p=>p.tags||[])]){const parts=normalizeCollection(value).split('/');let level=roots,prefix=[];for(const part of parts){if(!part)continue;const key=part.toLowerCase();if(!level.has(key))level.set(key,{label:part,path:[...prefix,part].join('/'),children:new Map()});const node=level.get(key);prefix=node.path.split('/');level=node.children}}
 const rows=[];const visit=(level,depth)=>{for(const node of [...level.values()].sort((a,b)=>a.label.localeCompare(b.label))){rows.push({path:node.path,label:node.label,depth});visit(node.children,depth+1)}};visit(roots,0);return rows}
function existingTags(){return collectionTree().map(t=>t.path)}
function parseTags(value){const known=new Map(existingTags().map(t=>[t.toLowerCase(),t]));const result=new Map();for(const part of value.split(',')){const tag=normalizeCollection(part);if(tag&&!result.has(tag.toLowerCase()))result.set(tag.toLowerCase(),known.get(tag.toLowerCase())||tag)}return [...result.values()]}
function collectionSettings(){return `<section class="panel"><h2>Collections & tags</h2><p>Rename or move collections, or remove tags from papers.</p><button type="button" class="button" data-manage-collections>Manage collections</button></section>`}
async function changeCollection(oldName,newName){
 if(saving)throw new Error('Please wait for the current save or upload.');
 const same=t=>t.toLowerCase()===oldName.toLowerCase()||t.toLowerCase().startsWith(oldName.toLowerCase()+'/');
 const remap=t=>target===null?[]:[target+t.slice(oldName.length)];
 if(!existingTags().some(same))throw new Error('This collection no longer exists.');
 let target=null;
 if(newName!==null){target=normalizeCollection(newName);if(!target||target.length>200||target.includes(','))throw new Error('Enter a collection name of 1–200 characters without commas.');if(target.toLowerCase().startsWith(oldName.toLowerCase()+'/'))throw new Error('A collection cannot be moved inside its own branch.');target=existingTags().find(t=>!same(t)&&t.toLowerCase()===target.toLowerCase())||target}
 if(target&&existingTags().some(t=>same(t)&&(target+t.slice(oldName.length)).length>200))throw new Error('The moved collection path would exceed 200 characters.');
 const beforePapers=papers,beforeSettings=settings;
 const unique=tags=>[...new Map(tags.map(t=>[t.toLowerCase(),t])).values()];
 papers=papers.map(p=>{if(!(p.tags||[]).some(same))return p;return {...p,tags:unique(p.tags.flatMap(t=>same(t)?remap(t):[t])),updated:Date.now()}});
 settings={...settings,collections:unique((settings.collections||[]).flatMap(t=>same(t)?remap(t):[t]))};
 if(target&&!settings.collections.some(t=>t.toLowerCase()===target.toLowerCase()))settings.collections.push(target);
 try{if(remoteMode)await persistRemote();else{await save();await saveSettings()}}
 catch(err){if(!remoteMode){papers=beforePapers;settings=beforeSettings}throw err}
 setCollectionFilters(activeCollections().flatMap(t=>same(t)?target===null?[]:[target+t.slice(oldName.length)]:[t]));
 return target;
}
function manageCollections(){
 const tags=collectionTree();
 modal(modalTitle('Manage collections.')+`<p class="collection-help">Drag a tag onto another tag to make it a child, or onto Top level to move it out. Click a tag to rename or delete it.</p><p id="collection-drag-status" class="collection-drag-status" role="status" aria-live="polite"></p><div id="collection-manager" class="collection-manager collection-tree-list"><div class="collection-root-drop" data-drop-parent="">${icon('library')}Top level <span>Drop a tag here to remove its parent</span></div>${tags.length?tags.map(({path:tag,label,depth})=>`<div class="collection-tree-entry collection-drop-row" data-drop-parent="${esc(tag)}" style="--collection-depth:${depth}"><button type="button" class="filter-tag collection-edit-tag" draggable="false" data-drag-collection="${esc(tag)}" data-edit-collection="${esc(tag)}" aria-label="Edit ${esc(tag)}" title="${esc(tag)} — drag to move, click to edit" aria-describedby="collection-drag-status"><span>${esc(label)}</span><span class="filter-tag-count">${collectionCount(tag)}</span></button></div>`).join(''):'<p>No collections yet. Create one or add tags to a paper.</p>'}</div><div class="modal-actions"><button type="button" class="button" data-close>Done</button><button type="button" class="button primary" id="add-collection">${icon('plus')}New collection</button></div>`);
 bindCollectionDragging();
}
function editCollection(tag){
 const parent=tag.includes('/')?tag.slice(0,tag.lastIndexOf('/')+1):'';
 modal(modalTitle('Edit collection.')+`<form id="edit-collection-form"><p class="collection-help">${esc(tag.replaceAll('/',' › '))} · ${collectionCount(tag)} papers</p><div class="field"><label for="edit-collection-name">Collection name</label><input id="edit-collection-name" value="${esc(tag.split('/').at(-1))}" required maxlength="200"><small>Renaming updates this collection and its children.</small></div><p id="edit-collection-error" class="error" role="alert"></p><div class="collection-editor-tools"><button type="button" class="button" id="edit-collection-move">Move to another parent</button><button type="button" class="button danger" id="edit-collection-delete">Delete collection</button></div><div class="modal-actions"><button type="button" class="button" id="edit-collection-back">Back</button><button type="submit" class="button primary">Save name</button></div></form>`);
 $('#edit-collection-back').onclick=manageCollections;
 $('#edit-collection-move').onclick=()=>moveCollectionDialog(tag);
 $('#edit-collection-delete').onclick=()=>confirmAction('Delete '+tag+'?',`Remove this collection branch from ${collectionCount(tag)} papers and from your collections? Your papers and notes are kept.`,async()=>{await changeCollection(tag,null);toast('Collection deleted.')});
 $('#edit-collection-form').onsubmit=async e=>{e.preventDefault();if(saving)return;try{const name=$('#edit-collection-name').value.trim();if(!name||name.includes('/'))throw new Error('Enter a name without /. Drag the tag to change its parent.');const target=parent+name;if(target!==tag&&existingTags().some(t=>t.toLowerCase()===target.toLowerCase()))throw new Error('A collection with that name already exists here.');await changeCollection(tag,target);render();manageCollections();toast('Collection renamed.')}catch(err){$('#edit-collection-error').textContent=err.message}};
}
function collectionDropAllowed(tag,parent){return !!tag&&parent.toLowerCase()!==tag.toLowerCase()&&!parent.toLowerCase().startsWith(tag.toLowerCase()+'/')}
async function dropCollection(tag,parent){
 if(saving)return;if(!collectionDropAllowed(tag,parent))throw new Error('A collection cannot be moved inside its own branch.');
 const target=(parent?parent+'/':'')+tag.split('/').at(-1);
 if(target.toLowerCase()===tag.toLowerCase())return;
 if(existingTags().some(t=>t.toLowerCase()===target.toLowerCase())){moveCollectionDialog(tag,parent);return}
 await moveCollection(tag,parent);render();manageCollections();toast('Collection moved.');
}
function collectionPreviewRows(tag,parent){
 const target=(parent?parent+'/':'')+tag.split('/').at(-1);
 return collectionTree().map(row=>{const moving=inCollection([row.path],tag),path=moving?target+row.path.slice(tag.length):row.path;return {...row,originalPath:row.path,path,depth:path.split('/').length-1,moving}}).sort((a,b)=>{const left=a.path.split('/'),right=b.path.split('/');for(let i=0;i<Math.min(left.length,right.length);i++){const order=left[i].localeCompare(right[i]);if(order)return order}return left.length-right.length});
}
function bindCollectionDragging(){
 const manager=$('#collection-manager'),status=$('#collection-drag-status');let dragged='',source=null,zone=null,touch=null,suppressClick=false,preview=null,previewTarget=null,origins=[],previewPoint=null;
 const clearZone=()=>{preview?.remove();preview=null;previewTarget=null;zone=null;manager.classList.remove('collection-previewing')};
 const clear=()=>{clearZone();origins.forEach(row=>row.classList.remove('collection-drag-origin'));origins=[];source?.classList.remove('collection-dragging');manager.classList.remove('collection-drag-in-progress');dragged='';source=null;touch=null;previewPoint=null};
 const handle=target=>target?.closest?.('[data-drag-collection]');
 const targetZone=target=>{const previewTag=target?.closest?.('[data-preview-tag]');if(previewTag){const path=previewTag.dataset.previewTag;if(inCollection([path],dragged))return previewTarget;return Array.from(manager.querySelectorAll('[data-drop-parent]')).find(row=>row.dataset.dropParent===path)||null}if(target?.closest?.('[data-collection-preview]'))return previewTarget;const found=target?.closest?.('[data-drop-parent]');return found&&manager.contains(found)?found:null};
 const highlight=target=>{const candidate=targetZone(target);if(!candidate){clearZone();return null}const parent=candidate.dataset.dropParent;if(!collectionDropAllowed(dragged,parent)){clearZone();status.textContent='A collection cannot be dropped into its own branch.';return null}if(zone!==candidate){clearZone();zone=candidate;previewTarget=candidate;preview=document.createElement('div');preview.className='collection-move-preview collection-tree-list';preview.dataset.collectionPreview='';preview.setAttribute('aria-hidden','true');preview.innerHTML=collectionPreviewRows(dragged,parent).map(t=>`<div class="collection-tree-entry collection-preview-row ${t.moving?'collection-preview-moving':''}" data-preview-tag="${esc(t.originalPath)}" style="--collection-depth:${t.depth}"><span class="filter-tag"><span>${esc(t.label)}</span><span class="filter-tag-count">${collectionCount(t.originalPath)}</span></span></div>`).join('');candidate.after(preview);const root=Array.from(manager.querySelectorAll('[data-drop-parent]')).find(row=>row.dataset.dropParent==='');preview.style.top=(root?root.getBoundingClientRect().bottom-manager.getBoundingClientRect().top+8:0)+'px';manager.classList.add('collection-previewing')}status.textContent='Release to move '+dragged.replaceAll('/',' › ')+(parent?' under '+parent.replaceAll('/',' › '):' to top level')+'.';return zone};
 const begin=grip=>{suppressClick=true;dragged=grip.dataset.dragCollection;source=grip.closest('[data-drop-parent]');source?.classList.add('collection-dragging');origins=Array.from(manager.querySelectorAll('[data-drop-parent]')).filter(row=>inCollection([row.dataset.dropParent],dragged));origins.forEach(row=>row.classList.add('collection-drag-origin'));manager.classList.add('collection-drag-in-progress');status.textContent='Drag '+dragged.replaceAll('/',' › ')+' onto its new parent or Top level.'};
 const finish=async(tag,parent)=>{try{await dropCollection(tag,parent)}catch(err){status.textContent=err.message;toast(err.message)}};
 manager.ondragstart=e=>{const grip=handle(e.target);if(saving||!grip||!manager.contains(grip)){e.preventDefault();return}begin(grip);e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragged)};
 manager.ondragover=e=>{if(!dragged||touch||saving)return;const valid=highlight(e.target);e.dataTransfer.dropEffect=valid?'move':'none';if(valid)e.preventDefault()};
 manager.ondragleave=e=>{if(!manager.contains(e.relatedTarget))clearZone()};
 manager.ondrop=async e=>{if(!dragged||touch)return;e.preventDefault();const destination=highlight(e.target);const tag=dragged,parent=destination?.dataset.dropParent;clear();if(parent!==undefined)await finish(tag,parent)};
 manager.ondragend=()=>{clear();status.textContent='';setTimeout(()=>{suppressClick=false},0)};
 manager.onclick=e=>{if(saving)return;if(suppressClick){suppressClick=false;return}const tag=e.target.closest('[data-edit-collection]');if(tag)editCollection(tag.dataset.editCollection)};
 // Use captured pointer gestures for mouse, touch and pen; native button dragging varies by browser.
 manager.onpointerdown=e=>{if(saving||e.button>0)return;const grip=handle(e.target);if(!grip||!manager.contains(grip))return;e.preventDefault();touch={id:e.pointerId,x:e.clientX,y:e.clientY,grip,started:false};grip.setPointerCapture(e.pointerId)};
 manager.onpointermove=e=>{if(!touch||touch.id!==e.pointerId)return;if(!touch.started){if(Math.hypot(e.clientX-touch.x,e.clientY-touch.y)<6)return;const pending=touch;begin(pending.grip);touch=pending;touch.started=true}e.preventDefault();if(!previewPoint||Math.hypot(e.clientX-previewPoint.x,e.clientY-previewPoint.y)>=14){const previous=zone;highlight(document.elementFromPoint(e.clientX,e.clientY));if(previous!==zone)previewPoint={x:e.clientX,y:e.clientY}}const dialog=$('#modal'),rect=dialog.getBoundingClientRect();if(e.clientY<rect.top+65)dialog.scrollTop-=16;else if(e.clientY>rect.bottom-65)dialog.scrollTop+=16};
 manager.onpointerup=async e=>{if(!touch||touch.id!==e.pointerId)return;const tag=dragged,parent=touch.started&&targetZone(document.elementFromPoint(e.clientX,e.clientY))?zone?.dataset.dropParent:undefined;const grip=touch.grip,wasDragging=touch.started;clear();if(grip.hasPointerCapture(e.pointerId))grip.releasePointerCapture(e.pointerId);if(!wasDragging)editCollection(grip.dataset.dragCollection);setTimeout(()=>{suppressClick=false},0);if(parent!==undefined)await finish(tag,parent)};
 manager.onpointercancel=()=>{clear();suppressClick=false;status.textContent='Move canceled.'};
 manager.onkeydown=e=>{if(e.key==='Escape'&&(dragged||touch)){e.preventDefault();e.stopPropagation();clear();suppressClick=false;status.textContent='Move canceled.'}};
}
async function moveCollection(tag,parent){
 const known=existingTags();const actual=known.find(t=>t.toLowerCase()===tag.toLowerCase());if(!actual)throw new Error('This collection no longer exists.');
 if(parent){parent=known.find(t=>t.toLowerCase()===parent.toLowerCase());if(!parent)throw new Error('The destination collection no longer exists.');if(parent.toLowerCase()===actual.toLowerCase()||parent.toLowerCase().startsWith(actual.toLowerCase()+'/'))throw new Error('A collection cannot be moved inside its own branch.')}
 const target=(parent?parent+'/':'')+actual.split('/').at(-1);if(target===actual)return actual;
 return changeCollection(actual,target);
}
function moveCollectionDialog(tag,destination){
 const parent=destination===undefined?(tag.includes('/')?tag.slice(0,tag.lastIndexOf('/')):''):destination;
 const options=collectionTree().filter(t=>t.path.toLowerCase()!==tag.toLowerCase()&&!t.path.toLowerCase().startsWith(tag.toLowerCase()+'/'));
 modal(modalTitle('Move collection.')+`<form id="move-collection-form"><p>Move <strong>${esc(tag.replaceAll('/',' › '))}</strong> and its children. Paper records keep their tags at the new location.</p><div class="field"><label for="move-collection-parent">Destination parent</label><select id="move-collection-parent"><option value="">Top level</option>${options.map(t=>`<option value="${esc(t.path)}" ${t.path===parent?'selected':''}>${esc(t.path.replaceAll('/',' › '))}</option>`).join('')}</select></div><p id="move-collection-preview" class="collection-help" role="status"></p><label id="move-merge-warning" class="auto-collection-check" hidden><input id="move-merge-confirm" type="checkbox">Merge with the collection already at this destination</label><div id="move-collection-error" class="error" role="alert"></div><div class="modal-actions"><button type="button" class="button" id="cancel-move-collection">Back</button><button class="button primary" id="save-move-collection" type="submit">Move collection</button></div></form>`);
 const target=()=>($('#move-collection-parent').value?$('#move-collection-parent').value+'/':'')+tag.split('/').at(-1);
 const collision=()=>target().toLowerCase()!==tag.toLowerCase()&&existingTags().some(t=>t.toLowerCase()===target().toLowerCase());
 const update=()=>{$('#move-collection-preview').textContent='New location: '+target().replaceAll('/',' › ');$('#move-merge-warning').hidden=!collision();$('#move-merge-confirm').checked=false};
 $('#move-collection-parent').value=parent;$('#move-collection-parent').onchange=update;update();$('#cancel-move-collection').onclick=manageCollections;
 $('#move-collection-form').onsubmit=async e=>{e.preventDefault();if(saving)return;const button=$('#save-move-collection');button.disabled=true;try{if(collision()&&!$('#move-merge-confirm').checked)throw new Error('Confirm the merge or choose a different parent.');await moveCollection(tag,$('#move-collection-parent').value);render();manageCollections();toast('Collection moved.')}catch(err){$('#move-collection-error').textContent=err.message}finally{button.disabled=false}};
}
function renameCollection(tag){
 modal(modalTitle('Rename collection.')+`<form id="rename-collection-form"><div class="field"><label for="rename-collection-name">Collection name</label><input id="rename-collection-name" value="${esc(tag)}" required maxlength="200"><small>Updates this collection and its descendants on every paper. Use / for layers, such as PQC/ML-DSA. Choosing an existing collection name merges the two collections.</small></div><div id="rename-collection-error" class="error" role="alert"></div><div class="modal-actions"><button type="button" class="button" id="back-to-collections">Back</button><button type="submit" class="button primary" id="save-collection-name">Save name</button></div></form>`);
 $('#back-to-collections').onclick=manageCollections;
 $('#rename-collection-form').onsubmit=async e=>{e.preventDefault();if(saving)return;const button=$('#save-collection-name');button.disabled=true;try{await changeCollection(tag,$('#rename-collection-name').value);render();manageCollections();toast('Collection updated.')}catch(err){$('#rename-collection-error').textContent=err.message}finally{button.disabled=false}};
}
function tagField(id,value=''){return `<div class="field tag-field"><label for="${id}">Collections / tags</label><input id="${id}" value="${esc(value)}" placeholder="Type to find a collection…" autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="${id}-suggestions" aria-describedby="${id}-help"><div id="${id}-suggestions" class="tag-suggestions" role="listbox" aria-label="Existing collections" hidden></div><small id="${id}-help">Choose an existing tag, or type a new one. Use / for layers (PQC/ML-DSA). Separate multiple tags with commas.</small></div>`}
function attachTagSuggestions(id){
 const input=$('#'+id),list=$('#'+id+'-suggestions');let matches=[],active=-1,dismissed=false;
 const token=()=>{const caret=input.selectionStart??input.value.length;const start=caret===0?0:input.value.lastIndexOf(',',caret-1)+1;const next=input.value.indexOf(',',caret);return {start,end:next<0?input.value.length:next}};
 const hide=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant')};
 const paint=()=>{list.innerHTML=matches.map((tag,i)=>`<button type="button" role="option" tabindex="-1" id="${id}-option-${i}" data-tag-index="${i}" aria-selected="${i===active}" class="${i===active?'active':''}">${esc(tag)}</button>`).join('');list.hidden=!matches.length;input.setAttribute('aria-expanded',String(!!matches.length));if(active>=0)input.setAttribute('aria-activedescendant',id+'-option-'+active);else input.removeAttribute('aria-activedescendant')};
 const update=()=>{if(dismissed)return;const {start,end}=token();const query=input.value.slice(start,end).trim().toLowerCase();const selected=new Set(parseTags(input.value.slice(0,start)+input.value.slice(end)).map(t=>t.toLowerCase()));matches=existingTags().filter(t=>!selected.has(t.toLowerCase())&&t.toLowerCase().includes(query)).sort((a,b)=>Number(b.toLowerCase().startsWith(query))-Number(a.toLowerCase().startsWith(query))||a.localeCompare(b));active=-1;paint()};
 const choose=index=>{const tag=matches[index];if(!tag)return;const {start,end}=token();const prefix=input.value.slice(0,start);const suffix=input.value.slice(end);const replacement=(prefix?' ':'')+tag+(suffix?'':', ');input.value=prefix+replacement+suffix;input.focus();input.setSelectionRange(prefix.length+replacement.length,prefix.length+replacement.length);hide();dismissed=true};
 input.oninput=()=>{dismissed=false;update()};input.onfocus=()=>{dismissed=false;update()};input.onclick=()=>{dismissed=false;update()};input.onblur=hide;
 input.onkeydown=e=>{if(e.isComposing)return;if(e.key==='Escape'&&!list.hidden){e.preventDefault();e.stopPropagation();dismissed=true;hide();return}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(list.hidden){dismissed=false;update()}if(matches.length){active=(active+(e.key==='ArrowDown'?1:active<0?0:-1)+matches.length)%matches.length;paint();$('#'+id+'-option-'+active)?.scrollIntoView({block:'nearest'})}}else if(e.key==='Enter'&&!list.hidden&&matches.length){e.preventDefault();choose(active<0?0:active)}};
 list.onmousedown=e=>e.preventDefault();list.onclick=e=>{const button=e.target.closest('[data-tag-index]');if(button)choose(Number(button.dataset.tagIndex))};
}
function abstractText(value){return String(value||'').replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,'').replace(/<[^>]*>/g,' ').replace(/&(?:amp|lt|gt|quot|apos|nbsp|#\d+|#x[0-9a-f]+);/gi,e=>{const named={'&amp;':'&','&lt;':'<','&gt;':'>','&quot;':'"','&apos;':"'",'&nbsp;':' '};if(named[e.toLowerCase()])return named[e.toLowerCase()];const code=e[2]?.toLowerCase()==='x'?parseInt(e.slice(3,-1),16):Number(e.slice(2,-1));return code>0&&code<=0x10ffff?String.fromCodePoint(code):e}).replace(/\s+/g,' ').trim().slice(0,20000)}
function abstractField(prefix,value=''){return `<div class="field"><label for="${prefix}-abstract">Abstract</label><textarea id="${prefix}-abstract" maxlength="20000" placeholder="Fetched when available; otherwise paste the abstract here.">${esc(value)}</textarea><small>Used to choose collections when you enable automatic tagging in Settings.</small></div>${remoteMode?`<button type="button" class="button" id="${prefix}-auto-tags" ${!aiConfigured||!settings.autoCollections?'disabled':''}>${icon('spark')}Suggest collections from abstract</button><small class="auto-tag-status" id="${prefix}-auto-status" role="status"></small>`:''}`}
function autoCollectionSettings(){if(!remoteMode)return '<section class="panel"><h2>Automatic collections</h2><p>Automatic tagging is available in the signed-in server app. You can use layered collections here, such as PQC/ML-DSA.</p></section>';return `<section class="panel"><h2>Automatic collections</h2><p>${aiConfigured?'OpenAI is configured on this server.':'The owner must add an OpenAI API key to the server configuration first.'} When enabled, adding a paper sends its title, abstract, and your collection names to OpenAI to choose suitable tags. API usage is billed to the server owner. Papers without abstracts remain available for manual tagging.</p><form id="auto-collections-form"><label class="auto-collection-check"><input id="auto-collections-enabled" type="checkbox" ${settings.autoCollections?'checked':''} ${!aiConfigured?'disabled':''}> Automatically tag new papers from their abstracts</label><label class="auto-collection-check"><input id="auto-collections-create" type="checkbox" ${settings.autoCreateCollections!==false?'checked':''}> Create collections when no existing collection fits</label><div class="field"><label for="collection-instructions">Classification preferences (optional)</label><textarea id="collection-instructions" maxlength="1000" placeholder="For example: use PQC as the parent, with ML-DSA and ML-KEM as children.">${esc(settings.collectionInstructions||'')}</textarea><small>Existing tag names must be reused, not recreated under another parent. Names are compared without regard to capitalization or surrounding spaces. Layers use /, for example PQC/ML-DSA. You can edit any suggested tag.</small></div><p id="auto-settings-error" class="error" role="alert"></p><button class="button" id="save-auto-settings">Save automatic collection settings</button></form></section>`}
function bindAutoSettings(){if(!remoteMode)return;$('#auto-collections-form').onsubmit=async e=>{e.preventDefault();if(saving)return;const b=$('#save-auto-settings');b.disabled=true;try{settings.autoCollections=$('#auto-collections-enabled').checked;settings.autoCreateCollections=$('#auto-collections-create').checked;settings.collectionInstructions=$('#collection-instructions').value.trim();await saveSettings();toast('Automatic collection settings saved.')}catch(err){$('#auto-settings-error').textContent=err.message}finally{b.disabled=false}}}
async function requestCollectionTags(title,abstract){if(!remoteMode||!settings.autoCollections)throw new Error('Enable automatic collections in Settings first.');if(!aiConfigured)throw new Error('OpenAI is not configured on this server.');if(!abstract.trim())throw new Error('Add an abstract first.');return (await remoteApi('/api/classify',{method:'POST',body:JSON.stringify({title,abstract,revision})})).tags}
function bindAbstractTags(prefix){if(!remoteMode)return;$('#'+prefix+'-auto-tags').onclick=async()=>{if(classifying||saving)return;const sequence=classificationSequence;const b=$('#'+prefix+'-auto-tags'),status=$('#'+prefix+'-auto-status');const title=$('#'+prefix+'-title').value.trim(),abstract=$('#'+prefix+'-abstract').value.trim();classifying=true;b.disabled=true;status.textContent='Reading abstract…';try{const tags=await requestCollectionTags(title,abstract);if(sequence!==classificationSequence)return;if($('#'+prefix+'-title').value.trim()!==title||$('#'+prefix+'-abstract').value.trim()!==abstract){status.textContent='The title or abstract changed. Run suggestions again.';return}const input=$('#'+prefix+'-tags');input.value=parseTags(input.value+', '+tags.join(', ')).join(', ');lastClassification=JSON.stringify([title,abstract]);status.textContent=tags.length?'Tags suggested. Save the paper to keep them and create any new collections.':'No suitable collections found. Choose tags manually.'}catch(err){if(sequence===classificationSequence)status.textContent=err.message}finally{if(sequence===classificationSequence){classifying=false;b.disabled=false}}}}
async function autoClassifyPaper(p){const sequence=classificationSequence;if(!remoteMode||!settings.autoCollections)return '';if(!p.abstract)return 'Paper saved. Add an abstract to use automatic collections.';if(lastClassification===JSON.stringify([p.title,p.abstract]))return '';classifying=true;try{const tags=await requestCollectionTags(p.title,p.abstract);p.tags=parseTags(p.tags.join(', ')+', '+tags.join(', '));return ''}catch{return 'Paper saved. Automatic tagging was unavailable; you can retry from the paper details.'}finally{if(sequence===classificationSequence)classifying=false}}
let addMode='url',lookedUpMetadata=null,metadataLookupSequence=0;
function addPaper(){addMode='url';renderAdd()}
function renderAdd(){lookedUpMetadata=null;metadataLookupSequence++;modal(modalTitle('Make room for a new idea.')+`<p style="font-size:12px">Add a paper from a link or enter your own citation details.</p><div class="tabs"><button data-add-tab="url" class="${addMode==='url'?'active':''}">Paper URL / DOI</button><button data-add-tab="manual" class="${addMode==='manual'?'active':''}">Manual entry</button></div><form id="add-form">${addMode==='url'?'<div class="field"><label for="paper-url">Paper URL or DOI</label><input id="paper-url" placeholder="https://eprint.iacr.org/2019/953 or 10.1137/0218012"><small>Paste a DOI, doi.org link, arXiv link, or IACR ePrint link, then click Look up metadata. For a publisher page, copy its DOI to look up the citation, or save the URL with your own details.</small></div><button type="button" class="button" id="lookup">'+icon('search')+'Look up metadata</button>':'<div class="field"><label for="paper-url">Paper URL or DOI</label><input id="paper-url" placeholder="Optional paper link or DOI"></div>'}<div class="field"><label for="paper-title">Title *</label><input id="paper-title" required maxlength="500" placeholder="The title of the paper"></div><div class="field"><label for="paper-authors">Authors</label><input id="paper-authors" placeholder="Separate authors with semicolons"></div><div class="two-fields"><div class="field"><label for="paper-year">Publication year</label><input id="paper-year" type="number" min="1400" max="2100" placeholder="2026"></div><div class="field"><label for="paper-venue">Conference / journal</label><input id="paper-venue" placeholder="e.g. EUROCRYPT"></div></div>${abstractField('paper')}${tagField('paper-tags')}<div class="two-fields"><div class="field"><label for="paper-status">Reading status</label><select id="paper-status"><option value="unread">Unread</option><option value="reading">Reading</option><option value="read">Read</option></select></div>${ratingField('paper-priority')}</div><div id="add-error" class="error" role="alert"></div><div class="modal-actions"><button type="button" class="button" data-close>Cancel</button><button class="button primary" id="save-paper" type="submit">${icon('plus')}Add to library</button></div></form>`);$('#paper-priority').value=3;attachTagSuggestions('paper-tags');bindAbstractTags('paper');$('#add-form').onsubmit=submitAdd;if($('#lookup'))$('#lookup').onclick=lookupMetadata;}
function paperInput(value){const clean=value.trim();return /^(?:link\.springer(?:nature)?\.com|dl\.acm\.org|ieeexplore\.ieee\.org|(?:export\.|www\.)?arxiv\.org|tches\.iacr\.org|eprint\.iacr\.org|ia\.cr)\//i.test(clean)?'https://'+clean:clean}
function getDoi(value){let clean=paperInput(value).replace(/^doi:\s*/i,'');try{const u=new URL(clean);if(!/^https?:$/.test(u.protocol)||u.username||u.password||u.port||! /^(?:dx\.)?doi\.org$/i.test(u.hostname))return '';clean=decodeURIComponent(u.pathname.slice(1))}catch{if(/^https?:/i.test(clean))return ''}return /^10\.\d{4,9}\/\S+$/i.test(clean)?clean:''}
function getEprintId(value){try{const u=new URL(paperInput(value));if(!/^https?:$/.test(u.protocol)||!['eprint.iacr.org','ia.cr'].includes(u.hostname)||u.username||u.password||u.port)return '';const id=u.pathname.match(/^\/((?:19|20)\d{2}\/\d{1,10})(?:\.pdf)?\/?$/)?.[1]||'';return id&&Number(id.split('/')[1])>0?id:''}catch{return ''}}
function getArxivId(value){try{const u=new URL(paperInput(value));if(!/^https?:$/.test(u.protocol)||!['arxiv.org','www.arxiv.org','export.arxiv.org'].includes(u.hostname)||u.username||u.password||u.port)return '';const id=u.pathname.match(/^\/(?:abs|pdf|html)\/(.+?)\/?$/)?.[1]?.replace(/\.pdf$/i,'')||'';return /^(?:\d{2}(?:0[1-9]|1[0-2])\.\d{4,5}|[a-z-]+(?:\.[a-z]{2})?\/\d{2}(?:0[1-9]|1[0-2])\d{3})(?:v[1-9]\d{0,3})?$/i.test(id)?id:''}catch{return ''}}
async function lookupPaper(value){const doi=getDoi(value);if(doi)return crossrefPaper((await fetchJson('https://api.crossref.org/works/'+encodeURIComponent(doi))).message);const arxivId=getArxivId(value);if(arxivId)return fetchJson('/api/arxiv?id='+encodeURIComponent(arxivId));const eprintId=getEprintId(value);if(eprintId)return fetchJson('/api/eprint?id='+encodeURIComponent(eprintId));throw new Error('Paste the paper’s DOI or doi.org link for citation lookup, or use an arXiv or IACR ePrint link. Other URLs can be saved with manual citation details.')}
async function fetchJson(url,options={}){const r=await fetch(url,{...options,signal:AbortSignal.timeout(20000)});if(!r.ok){const data=await r.json().catch(()=>({}));throw new Error(typeof data.error==='string'?data.error:`Service returned ${r.status}. Please try again.`)}return r.json()}
function crossrefVenue(w){const venue=w['container-title']?.[0]||w.event?.name||'';if(/\bACM\b/i.test(venue)&&/Conference on Computer and Communications Security/i.test(venue))return 'ACM CCS';if(/^IEEE Transactions on Information Forensics (?:and|&) Security$/i.test(venue.trim()))return 'IEEE TIFS';return venue}
function crossrefPaper(w){return {id:crypto.randomUUID(),title:w.title?.[0]||'Untitled paper',authors:(w.author||[]).map(a=>[a.given,a.family].filter(Boolean).join(' ')).filter(Boolean).join('; '),year:(w.published?.['date-parts']||w.issued?.['date-parts'])?.[0]?.[0]||'',venue:crossrefVenue(w),abstract:abstractText(w.abstract),doi:w.DOI||'',url:w.URL||'',tags:[],status:'unread',importance:3,notes:'',added:Date.now(),updated:Date.now(),metadataSource:'Crossref',type:w.type}}
async function lookupMetadata(){const source=paperInput($('#paper-url').value);const sequence=++metadataLookupSequence;lookedUpMetadata=null;const b=$('#lookup');b.disabled=true;b.textContent='Looking up\u2026';try{const p=await lookupPaper(source);if(sequence!==metadataLookupSequence||source!==paperInput($('#paper-url')?.value||'')||addMode!=='url')return;$('#paper-title').value=p.title;$('#paper-authors').value=p.authors;$('#paper-year').value=p.year;$('#paper-venue').value=p.venue;$('#paper-abstract').value=p.abstract||'';lookedUpMetadata={...p,source};$('#add-error').textContent='';toast('Citation details found. Review before saving.')}catch(e){if(sequence===metadataLookupSequence)$('#add-error').textContent=e.message+' You can still enter details manually.'}finally{b.disabled=false;b.innerHTML=icon('search')+'Look up metadata'}}
async function submitAdd(e){e.preventDefault();if(saving||classifying)return;const error=$('#add-error');const b=$('#save-paper');b.disabled=true;try{const source=paperInput($('#paper-url')?.value||'');const metadata=lookedUpMetadata?.source===source?lookedUpMetadata:null;const doi=getDoi(source)||metadata?.doi||'';if($('#lookup')?.disabled)throw new Error('Wait for the citation lookup to finish.');if(source&&!doi&&!safeUrl(source))throw new Error('Enter a valid http or https paper URL.');const arxivId=getArxivId(source).replace(/v\d+$/i,'').toLowerCase();if(arxivId&&papers.some(p=>getArxivId(p.url||'').replace(/v\d+$/i,'').toLowerCase()===arxivId))throw new Error('This arXiv paper is already in your library.');const eprintId=getEprintId(source);if(eprintId&&papers.some(p=>getEprintId(p.url||'')===eprintId))throw new Error('This ePrint paper is already in your library.');if(doi&&papers.some(p=>p.doi?.toLowerCase()===doi.toLowerCase()))throw new Error('This DOI is already in your library.');const p={id:crypto.randomUUID(),title:$('#paper-title').value.trim(),authors:$('#paper-authors').value.trim(),year:Number($('#paper-year').value)||'',venue:$('#paper-venue').value.trim(),tags:parseTags($('#paper-tags').value),abstract:$('#paper-abstract').value.trim(),status:$('#paper-status').value,importance:readRating('paper-priority'),url:safeUrl(source)||(doi?'https://doi.org/'+doi:''),doi,metadataSource:metadata?.metadataSource||'',type:metadata?.type||'',notes:'',added:Date.now(),updated:Date.now()};if(!p.title)throw new Error('Enter a paper title.');const sequence=classificationSequence;const notice=await autoClassifyPaper(p);if(sequence!==classificationSequence)return;papers.unshift(enrichVenue(p));await save();close();render();toast(notice||'Paper added. A new idea, collected.')}catch(err){error.textContent=err.message}finally{b.disabled=false}}
function details(id,external=false){const p=(external?recommendations:papers).find(p=>p.id===id);if(!p)return;modal(modalTitle(p.title)+`<p style="font-size:12px">${esc(p.authors)} · ${esc(p.year||'Year not recorded')}</p><div class="detail-links">${safeUrl(p.url|| (p.doi?'https://doi.org/'+p.doi:''))?`<a class="button" href="${esc(safeUrl(p.url||'https://doi.org/'+p.doi))}" target="_blank" rel="noopener noreferrer">${icon('link')}Open paper ↗</a>`:''}${!external?`<button class="button" data-cite="${esc(p.id)}">${icon('download')}Cite</button>`:''}</div>${external?`<p>Found via Crossref. Check the publisher page for the full text and publication details.</p><div class="modal-actions"><button class="button primary" data-import="${esc(p.id)}">Add to library</button></div>`:`<form id="detail-form"><div class="two-fields"><div class="field"><label for="detail-status">Reading status</label><select id="detail-status"><option value="unread">Unread</option><option value="reading">Reading</option><option value="read">Read</option></select></div>${ratingField('detail-priority',p.importance)}</div><div class="field"><label for="detail-title">Title</label><input id="detail-title" value="${esc(p.title)}" required></div><div class="field"><label for="detail-authors">Authors</label><input id="detail-authors" value="${esc(p.authors)}"></div><div class="two-fields"><div class="field"><label for="detail-year">Publication year</label><input id="detail-year" type="number" min="1400" max="2100" value="${esc(p.year)}"></div><div class="field"><label for="detail-venue">Conference / journal</label><input id="detail-venue" value="${esc(p.venue)}"></div></div><div class="field"><label for="detail-url">Paper source link</label><input id="detail-url" type="url" value="${esc(p.url||'')}" placeholder="https://…"></div>${abstractField('detail',p.abstract||'')}${tagField('detail-tags',p.tags.join(', '))}<div class="field"><label for="detail-notes">Reading notes</label><textarea id="detail-notes" placeholder="Key ideas, questions, and things to come back to…">${esc(p.notes)}</textarea></div><details><summary style="font-size:12px;cursor:pointer">Venue rank & impact factor</summary><p style="font-size:11px">Record a metric from a source such as CORE or Journal Citation Reports. These are venue metrics; they are not a score for this paper.</p><div class="two-fields"><div class="field"><label for="metric-type">Metric</label><select id="metric-type"><option>CORE rank</option><option>Journal impact factor</option><option>SJR quartile</option></select></div><div class="field"><label for="metric-value">Value</label><input id="metric-value" value="${esc(p.rank||'')}" placeholder="e.g. A* or 4.2"></div></div><div class="two-fields"><div class="field"><label for="metric-year">Metric year</label><input id="metric-year" type="number" min="2000" max="2100" value="${esc(p.metricYear||'')}" placeholder="2025"></div><div class="field"><label for="metric-source">Source URL</label><input id="metric-source" type="url" value="${esc(p.metricSource||'')}" placeholder="https://…"></div></div>${safeUrl(p.metricSource)?`<a href="${esc(p.metricSource)}" target="_blank" rel="noopener noreferrer" style="font-size:11px">View recorded source ↗</a>`:''}</details><div id="detail-error" class="error"></div><div class="modal-actions"><button type="button" class="button danger" data-delete="${esc(p.id)}">Remove paper</button><button class="button primary" type="submit">Save changes</button></div></form>`}`);if(!external){attachTagSuggestions('detail-tags');bindAbstractTags('detail');$('#detail-status').value=p.status;$('#detail-priority').value=normalizeImportance(p.importance);$('#metric-type').value=p.metricType||'CORE rank';$('#detail-form').onsubmit=async e=>{try{e.preventDefault();if(saving||classifying)return;const rank=$('#metric-value').value.trim();if(rank&&(!$('#metric-year').value||!safeUrl($('#metric-source').value))){$('#detail-error').textContent='Add a year and a valid source URL for the venue metric.';return}Object.assign(p,{title:$('#detail-title').value.trim(),authors:$('#detail-authors').value.trim(),year:Number($('#detail-year').value)||'',venue:$('#detail-venue').value.trim(),status:$('#detail-status').value,importance:readRating('detail-priority'),tags:parseTags($('#detail-tags').value),abstract:$('#detail-abstract').value.trim(),notes:$('#detail-notes').value,url:safeUrl($('#detail-url').value.trim()),rank,metricType:$('#metric-type').value,metricYear:$('#metric-year').value,metricSource:$('#metric-source').value,updated:Date.now()});await save();close();render();toast('Paper updated.')}catch(err){if(confirmed&&papers.some(a=>a.id===id)){details(id);$('#detail-error').textContent=err.message}else toast(err.message)}};}}
function bibEscape(s){return String(s||'').replace(/[\\{}%&#_$]/g,c=>'\\'+c)}
function citation(p,format){const isPreprint=p.type==='posted-content'||(!p.type&&/Cryptology ePrint Archive|^arXiv$/i.test(p.venue||''));const isConference=!isPreprint&&/proceedings|conference|symposium|EUROCRYPT/i.test(p.type||p.venue);const authors=p.authors.split(';').map(a=>a.trim()).filter(Boolean);if(format==='plain')return `${authors.join(', ')}${p.year?' ('+p.year+').':'.'} ${p.title}. ${p.venue||''}.${p.doi?' https://doi.org/'+p.doi:p.url?' '+p.url:''}`;if(format==='ris')return `TY  - ${isConference?'CPAPER':'JOUR'}\nTI  - ${p.title}\n${authors.map(a=>'AU  - '+a).join('\n')}\nPY  - ${p.year}\nJO  - ${p.venue}\nDO  - ${p.doi||''}\nUR  - ${p.url||''}\nER  -`;const name=authors[0]?.split(' ').at(-1)?.replace(/[^a-zA-Z]/g,'')||'paper';return `@${isPreprint?'misc':isConference?'inproceedings':'article'}{${name}${p.year||''}_${p.id.slice(-4)},\n  title = {${bibEscape(p.title)}},\n  author = {${authors.map(bibEscape).join(' and ')}},\n  year = {${p.year}},\n  ${isPreprint?'howpublished':isConference?'booktitle':'journal'} = {${bibEscape(p.venue)}}${p.doi?',\n  doi = {'+bibEscape(p.doi)+'}':''}${p.url?',\n  url = {'+bibEscape(p.url)+'}':''}\n}`}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function cite(id){const list=id?papers.filter(p=>p.id===id):papers;let format='bibtex';modal(modalTitle(id?'A citation, ready to go.':'Export your library.')+`<div class="field"><label for="cite-format">Citation format</label><select id="cite-format"><option value="bibtex">BibTeX</option><option value="ris">RIS</option><option value="plain">Plain text</option></select></div><p style="font-size:11px">${list.length} ${list.length===1?'paper':'papers'} · Review metadata for your preferred citation style.</p><pre class="citation-block" id="citation-output"></pre><div class="modal-actions"><button class="button" id="copy-citation">Copy citations</button><button class="button primary" id="download-citation">${icon('download')}Download</button></div>`);const content=()=>list.map(p=>citation(p,format)).join('\n\n');$('#citation-output').textContent=content();$('#cite-format').onchange=e=>{format=e.target.value;$('#citation-output').textContent=content()};$('#copy-citation').onclick=async()=>{try{await navigator.clipboard.writeText(content());toast('Citations copied.')}catch{toast('Clipboard unavailable. Use Download instead.')}};$('#download-citation').onclick=()=>download('folio-citations.'+({bibtex:'bib',ris:'ris',plain:'txt'}[format]),content())}
function pickPaper(){const list=filtered().filter(p=>p.status==='unread');if(!list.length){if(papers.some(p=>p.status==='unread'))toast('No unread papers match your current filters.');else navigate('discover');return}let candidates=list;if($('#prefer-important')?.checked!==false){const highest=Math.max(...list.map(p=>normalizeImportance(p.importance)));candidates=list.filter(p=>normalizeImportance(p.importance)===highest)}const chosen=$('#random-pick')?.checked?candidates[Math.floor(Math.random()*candidates.length)]:[...candidates].sort((a,b)=>a.added-b.added)[0];details(chosen.id);toast('Picked from your unread papers.')}
function renderDiscover(){const tags=[...new Set(papers.flatMap(p=>p.tags))].slice(0,4);$('#main').innerHTML=heading('Follow your curiosity.','Find papers beyond your library, guided by what interests you.',false)+`<section class="hero"><div class="hero-content"><div class="eyebrow">${icon('compass')} OPEN A NEW CHAPTER</div><h2>There’s always another idea to explore.</h2><p>Search live scholarly metadata, or use your library’s topics as a starting point.</p><button class="button" id="recommend">${icon('spark')}Recommend from my interests ${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true"><div class="art-ring"></div><div class="book-cover"></div><div class="book-front"><small>NEW PERSPECTIVES</small><em>Stay<br>curious.</em><div class="lines"></div></div><span class="spark">✦</span></div></section><form class="discover-search" id="discover-form"><label class="search">${icon('search')}<input id="discover-query" placeholder="Explore a topic, title, or author…" aria-label="Search scholarly papers" required></label><button class="button primary" id="discover-submit">Find papers</button></form><div class="tags">${tags.map(t=>`<button class="button" data-discover-topic="${esc(t)}">${esc(t)}</button>`).join('')}</div><div class="section-title"><h2>Beyond your library</h2><span class="subtle-link">Live metadata by Crossref</span></div><div id="discover-message" class="discover-message">${esc(discoverState||'Choose a topic to discover papers. Recommendations appear only when you ask.')}</div><div id="discover-results" class="paper-grid">${recommendations.map(p=>card(p,true)).join('')}</div>`;$('#discover-form').onsubmit=e=>{e.preventDefault();searchDiscovery($('#discover-query').value)};$('#recommend').onclick=()=>{const interests=papers.filter(p=>normalizeImportance(p.importance)>=4).flatMap(p=>p.tags);const topic=[...new Set(interests)].slice(0,2).join(' ')||tags.slice(0,2).join(' ');if(!topic){toast('Add tags to your papers, or search a topic.');return}$('#discover-query').value=topic;searchDiscovery(topic)};}
let searchSequence=0;
async function searchDiscovery(topic){const seq=++searchSequence;const b=$('#discover-submit');b.disabled=true;$('#discover-message').textContent='Looking for new perspectives…';try{const data=await fetchJson('https://api.crossref.org/works?query.bibliographic='+encodeURIComponent(topic)+'&rows=40');if(seq!==searchSequence||view!=='discover')return;const existing=new Set(papers.map(p=>(p.doi||'').toLowerCase()));const titles=new Set(papers.map(p=>p.title.toLowerCase()));const seen=new Set();recommendations=data.message.items.filter(w=>['journal-article','proceedings-article','posted-content','dissertation'].includes(w.type)).map(crossrefPaper).filter(p=>!existing.has(p.doi.toLowerCase())&&!titles.has(p.title.toLowerCase())).filter(p=>{const t=p.title.toLowerCase();if(seen.has(t))return false;seen.add(t);return true}).slice(0,12).map(p=>({...p,tags:[topic.length>35?'Related research':topic]}));discoverState=`${recommendations.length} papers related to “${topic}” · Papers already in your library are excluded.`;$('#discover-message').textContent=discoverState;$('#discover-results').innerHTML=recommendations.length?recommendations.map(p=>card(p,true)).join(''):'<div class="empty">No new papers found. Try a broader topic.</div>'}catch(e){if(view==='discover'&&seq===searchSequence){$('#discover-message').textContent=e.message+' Your existing results are still shown.'}}finally{b.disabled=false}}
async function importPaper(id){if(saving||classifying)return;const p=recommendations.find(p=>p.id===id);if(!p)return;if(papers.some(a=>a.doi&&a.doi===p.doi)){toast('Already in your library.');return}const record=enrichVenue({...p,added:Date.now(),updated:Date.now()});const notice=await autoClassifyPaper(record);papers.unshift(record);recommendations=recommendations.filter(a=>a.id!==id);await save();close();render();toast(notice||'A new perspective added to your library.')}
function renderSettings(){if(remoteMode){renderRemoteSettings();return}$('#main').innerHTML=heading('Your library, your way.','Manage collections, citations, and library backups.',false)+`${collectionSettings()}${autoCollectionSettings()}<section class="panel"><h2>Local backup & recovery</h2><p>Your citations, links, tags, and notes are saved in this browser. Export a JSON backup before clearing browser data.</p><div class="setting-row"><button id="json-export" class="button">${icon('download')}Export library JSON</button><button id="json-import" class="button">Import library JSON</button><input type="file" id="json-file" accept="application/json,.json" hidden><button id="settings-cite" class="button">Export citations</button></div></section>${papers.some(p=>p.sample)?'<section class="panel danger-zone"><div><h2>Make it your own</h2><p>Remove sample papers to start with your own research.</p></div><button class="button danger" id="remove-samples">Remove samples</button></section>':''}`;$('#json-export').onclick=()=>download('folio-library.json',JSON.stringify({version:1,papers,exported:new Date().toISOString()},null,2),'application/json');$('#json-import').onclick=()=>$('#json-file').click();$('#settings-cite').onclick=()=>cite();$('#json-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw new Error('Library JSON must be smaller than 10 MB.');mergeBackup(JSON.parse(await file.text()));await save();render();toast('Library backup merged.')}catch(err){toast('Import failed: '+err.message)}};}
function validateBackup(data){if(data?.version!==1||!Array.isArray(data.papers)||data.papers.length>10000)throw new Error('Not a supported Folio library backup.');return data.papers.map(p=>{if(typeof p.id!=='string'||p.id.length>100||!p.id||typeof p.title!=='string'||!p.title.trim())throw new Error('Invalid paper record.');return {id:p.id,title:p.title.slice(0,500),authors:String(p.authors||'').slice(0,5000),year:Number(p.year)||'',venue:String(p.venue||'').slice(0,1000),abstract:String(p.abstract||'').slice(0,20000),tags:Array.isArray(p.tags)?p.tags.filter(t=>typeof t==='string').slice(0,50):[],status:['read','unread','reading'].includes(p.status)?p.status:'unread',importance:normalizeImportance(p.importance),url:safeUrl(p.url),doi:getDoi(String(p.doi||'')),notes:String(p.notes||'').slice(0,100000),added:Number(p.added)||Date.now(),updated:Number(p.updated)||Number(p.added)||Date.now(),sample:p.sample===true,rank:String(p.rank||''),metricType:String(p.metricType||''),metricYear:String(p.metricYear||''),metricSource:safeUrl(p.metricSource),type:String(p.type||'')}})}
function mergeBackup(data){const incoming=validateBackup(data);const map=new Map(papers.map(p=>[p.id,citationOnly(p)]));for(const p of incoming){const current=map.get(p.id);if(!current||p.updated>current.updated)map.set(p.id,p)}papers=[...map.values()]}
function confirmAction(title,message,action){modal(modalTitle(title)+`<p>${esc(message)}</p><div class="modal-actions"><button class="button" data-close>Cancel</button><button class="button primary" id="confirm-action">Confirm</button></div>`);$('#confirm-action').onclick=async()=>{try{if(saving)return;await action();close();render()}catch(e){toast(e.message)}}}
document.addEventListener('click',async e=>{try{if(saving)return;const b=e.target.closest('button,a');if(!b)return;if(b.hasAttribute('data-choose-collections'))chooseCollections();if(b.hasAttribute('data-manage-collections'))manageCollections();if(b.dataset.view)navigate(b.dataset.view);if(b.dataset.collection)toggleCollection(b.dataset.collection);if(b.hasAttribute('data-filter-tag'))toggleCollection(b.dataset.filterTag);if(b.hasAttribute('data-close'))close();if(b.dataset.paper)details(b.dataset.paper);if(b.dataset.external)details(b.dataset.external,true);if(b.dataset.ratingInput){const id=b.dataset.ratingInput,value=Number(b.dataset.ratingValue);$('#'+id).value=value;$('#'+id+'-stars').innerHTML=ratingStars(value,'data-rating-input="'+esc(id)+'"')}if(b.dataset.ratePaper){const p=papers.find(p=>p.id===b.dataset.ratePaper);if(p){p.importance=Number(b.dataset.ratingValue);p.updated=Date.now();await save();render()}}if(b.dataset.import)await importPaper(b.dataset.import);if(b.dataset.cite)cite(b.dataset.cite);if(b.dataset.delete)confirmAction('Remove this paper?','This removes the citation, link, and notes from your library.',async()=>{const p=papers.find(p=>p.id===b.dataset.delete);papers=papers.filter(item=>item.id!==p.id);await save();toast('Paper removed.')});if(b.dataset.addTab){addMode=b.dataset.addTab;renderAdd()}if(b.dataset.layout){layout=b.dataset.layout;render()}if(b.dataset.discoverTopic){$('#discover-query').value=b.dataset.discoverTopic;searchDiscovery(b.dataset.discoverTopic)}if(['add-paper','empty-add'].includes(b.id))addPaper();if(['top-export','export-library'].includes(b.id))cite();if(b.id==='pick-paper')pickPaper();if(b.id==='remove-samples')confirmAction('Start with your own papers?','Remove the sample papers. Papers you added yourself will stay in your library.',async()=>{papers=papers.filter(p=>!p.sample);await save();toast('Sample papers removed.')});if(b.id==='add-collection'){modal(modalTitle('A new collection.')+'<form id="collection-form"><div class="field"><label for="collection-name">Collection name</label><input id="collection-name" required maxlength="200" placeholder="e.g. PQC/ML-DSA"><small>Use / to create a child collection.</small></div><div class="modal-actions"><button class="button primary">Create collection</button></div></form>');$('#collection-form').onsubmit=async e=>{try{e.preventDefault();if(saving)return;const t=normalizeCollection($('#collection-name').value);if(t.length>200||t.includes(','))throw new Error('Use a name up to 200 characters without commas.');if(!t)return;settings.collections=[...new Set([...(settings.collections||[]),t])];await saveSettings();close();navigate('library',t);toast('Collection created. Add its tag to any paper.')}catch(err){toast(err.message)}}}}catch(err){toast(err.message)}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
hydrate();restoreCollectionHash(location.hash.slice(1));if(remoteMode)startRemote();else render();

window.addEventListener('hashchange',()=>{if(remoteMode&&invitationToken()){showLogin();return}if(restoreCollectionHash(location.hash.slice(1)))render()});


async function remoteApi(path,options={}){
 const epoch=accountEpoch;
 const r=await fetch(path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,...(currentUser?{'X-Folio-User':String(currentUser.id)}:{}),...options.headers},signal:AbortSignal.timeout(20000)});
 const data=await r.json();
 if(epoch!==accountEpoch)throw new Error('The account changed while this request was running.');
 if(!r.ok){if(data.accountChanged||(r.status===401&&!['/api/login','/api/register','/api/password'].includes(path)))showLogin();const err=new Error(data.error||'Server request failed.');err.status=r.status;err.library=data.library;throw err}return data;
}
function acceptRemote(data){if(data.user&&currentUser?.id!==data.user.id){const sessionToken=csrf;clearAccountState();csrf=sessionToken;currentUser=data.user}papers=data.papers.map(citationOnly);settings=citationSettings(data.settings);revision=data.revision;confirmed=structuredClone(data)}
async function persistRemote(){
 if(saving)throw new Error('A save is in progress. Please wait.');
 saving=true;
 try{const data=await remoteApi('/api/library',{method:'PUT',body:JSON.stringify({papers,settings,revision})});acceptRemote(data);updateSidebar()}
 catch(err){if(err.library)acceptRemote(err.library);else if(confirmed)acceptRemote(confirmed);render();toast(err.message);throw err}
 finally{saving=false}
}
function clearAccountState(){accountEpoch++;currentUser=null;papers=[];settings={};confirmed=null;revision=0;csrf='';recommendations=[];discoverState='';searchSequence++;metadataLookupSequence++;lookedUpMetadata=null;collection='';extraCollections=[];collectionMatch='any';query='';statusFilter='all';priorityFilter='all';close()}
function invitationToken(){return location.hash.match(/^#invite=([a-f0-9]{64})$/)?.[1]||''}
function showLogin(){
 clearAccountState();updateSidebar();const invitation=invitationToken();
 $('#main').innerHTML=heading(invitation?'Your research starts here.':'Your research, securely collected.',invitation?'Create your own account with this invitation.':'Sign in to your private paper library.',false)+`<section class="panel"><form id="login-form"><div class="field"><label for="login-username">Username</label><input id="login-username" autocomplete="username" required minlength="3" maxlength="40" placeholder="${invitation?'Choose a username':'owner'}"><small>3–40 letters, numbers, dots, underscores, or hyphens.</small></div><div class="field"><label for="login-password">Password</label><input id="login-password" type="password" autocomplete="${invitation?'new-password':'current-password'}" required ${invitation?'minlength="16"':''} maxlength="1024">${invitation?'<small>Use at least 16 characters.</small>':''}</div>${invitation?'<div class="field"><label for="register-confirm">Confirm password</label><input id="register-confirm" type="password" autocomplete="new-password" required maxlength="1024"></div>':''}<div class="error" id="login-error" role="alert"></div><button class="button primary" id="login-submit">${invitation?'Create account':'Sign in'}</button></form>${invitation?'<button type="button" class="button" id="return-login">Already have an account? Sign in</button>':'<p>New accounts require an invitation from the owner.</p>'}</section>`;
 if(invitation)$('#return-login').onclick=()=>{location.hash='library';showLogin()};
 $('#login-form').onsubmit=async e=>{e.preventDefault();const b=$('#login-submit');b.disabled=true;const password=$('#login-password').value;try{if(invitation&&password!==$('#register-confirm').value)throw new Error('The passwords do not match.');const data=await remoteApi(invitation?'/api/register':'/api/login',{method:'POST',body:JSON.stringify({username:$('#login-username').value,password,...(invitation?{invitation}:{})})});currentUser=data.user;aiConfigured=data.aiConfigured===true;csrf=data.csrf;view='library';if(invitation){window.history?.replaceState(null,'',location.pathname+location.search+'#library');location.hash='library'}await loadRemote();}catch(err){$('#login-error').textContent=err.message}finally{b.disabled=false}};
}
async function loadRemote(){acceptRemote(await remoteApi('/api/library'));render()}
async function startRemote(){
 if(invitationToken()){showLogin();return}
 $('#storage-label').textContent='Saved on your server';$('.local-status').innerHTML='<i></i> Server library';
 $('#main').innerHTML=heading('Opening your library…','Connecting to your server.',false);
 try{const session=await remoteApi('/api/session');currentUser=session.user||null;aiConfigured=session.aiConfigured===true;csrf=session.csrf;await loadRemote()}catch(err){if(err.status!==401){$('#main').innerHTML=heading('Cannot reach your library.',esc(err.message),false)+`<button class="button" id="retry-server">Try again</button>`;$('#retry-server').onclick=startRemote}}
}
function accountSettings(){return `<section class="panel"><h2>Your account</h2><p>Signed in as <strong>${esc(currentUser?.username||'')}</strong>. Your library is private to this account.</p><form id="password-form"><div class="field"><label for="current-password">Current password</label><input id="current-password" type="password" autocomplete="current-password" required maxlength="1024"></div><div class="two-fields"><div class="field"><label for="new-password">New password</label><input id="new-password" type="password" autocomplete="new-password" required minlength="16" maxlength="1024"></div><div class="field"><label for="confirm-password">Confirm new password</label><input id="confirm-password" type="password" autocomplete="new-password" required maxlength="1024"></div></div><p class="error" id="password-error" role="alert"></p><button class="button" id="change-password">Change password</button></form>${currentUser?.role==='owner'?'<div class="setting-row"><button type="button" class="button" id="manage-users">Manage users & invitations</button></div>':''}</section>`}
async function manageUsers(){
 modal(modalTitle('Users & invitations.')+'<p>Loading accounts…</p>');
 try{const [users,invites]=await Promise.all([remoteApi('/api/admin/users'),remoteApi('/api/admin/invitations')]);if(currentUser?.role!=='owner')return;
 modal(modalTitle('Users & invitations.')+`<p>Each user has a private library for citations, links, tags, and notes. Invitations can be used by multiple people until they expire after seven days or you revoke them.</p><div id="account-manager">${users.users.map(user=>`<div class="collection-manager-row"><div><strong>${esc(user.username)}</strong><small>${user.role==='owner'?'Owner':user.enabled?'Active':'Disabled'}</small></div>${user.role==='owner'?'':`<button type="button" class="button" data-account-id="${user.id}" data-account-enable="${user.enabled?'false':'true'}">${user.enabled?'Disable':'Enable'}</button>`}</div>`).join('')}<h3>Active invitations</h3>${invites.invitations.length?invites.invitations.map(invite=>`<div class="collection-manager-row"><span>Expires ${esc(new Date(invite.expires).toLocaleDateString())}</span><button type="button" class="button danger" data-revoke-invite="${esc(invite.id)}">Revoke</button></div>`).join(''):'<p>No active invitations.</p>'}</div><div class="field"><label for="new-invitation">New invitation link</label><input id="new-invitation" readonly placeholder="Create an invitation to get a link"><small>Share privately. Copy the link now; it cannot be retrieved later.</small></div><p id="account-error" class="error" role="alert"></p><div class="modal-actions"><button type="button" class="button" data-close>Done</button><button type="button" class="button" id="copy-invitation">Copy link</button><button type="button" class="button primary" id="create-invitation">Create invitation</button></div>`);
 $('#create-invitation').onclick=async()=>{const b=$('#create-invitation');b.disabled=true;try{const invite=await remoteApi('/api/admin/invitations',{method:'POST',body:'{}'});$('#new-invitation').value=invite.url;toast('Invitation created. Copy the link before closing.')}catch(err){$('#account-error').textContent=err.message}finally{b.disabled=false}};
 $('#copy-invitation').onclick=async()=>{try{const link=$('#new-invitation').value;if(!link)throw new Error('Create an invitation first.');await navigator.clipboard.writeText(link);toast('Invitation link copied.')}catch(err){$('#account-error').textContent=err.message||'Copy the link manually.'}};
 $('#account-manager').onclick=async e=>{const b=e.target.closest('button');if(!b)return;b.disabled=true;try{if(b.dataset.revokeInvite)await remoteApi('/api/admin/invitations/'+b.dataset.revokeInvite,{method:'DELETE',body:'{}'});if(b.dataset.accountId)await remoteApi('/api/admin/users/'+b.dataset.accountId,{method:'PATCH',body:JSON.stringify({enabled:b.dataset.accountEnable==='true'})});await manageUsers()}catch(err){$('#account-error').textContent=err.message}finally{b.disabled=false}};
 }catch(err){if(currentUser?.role==='owner')modal(modalTitle('Users & invitations.')+`<p class="error">${esc(err.message)}</p>`)}
}
function renderRemoteSettings(){
 $('#main').innerHTML=heading('Your library, wherever you read.','Your citations, links, and reading notes in one place.',false)+`${accountSettings()}${collectionSettings()}${autoCollectionSettings()}<section class="panel"><h2>Server library & recovery</h2><p>Your private library loads on every signed-in device. Refresh to see edits made elsewhere. Conflicting saves load your latest library for review. JSON exports contain citation details, links, tags, and notes.</p><div class="setting-row"><button class="button" id="refresh-library">Reload from server</button><button class="button" id="json-export">Export library JSON</button><button class="button" id="json-import">Import library JSON</button><button class="button" id="logout">Sign out</button><input type="file" id="json-file" accept="application/json,.json" hidden></div><p>To migrate a browser library, export its JSON and import it here.</p></section>`;
 bindAutoSettings();
 $('#password-form').onsubmit=async e=>{e.preventDefault();const b=$('#change-password');b.disabled=true;try{if($('#new-password').value!==$('#confirm-password').value)throw new Error('The passwords do not match.');const result=await remoteApi('/api/password',{method:'POST',body:JSON.stringify({currentPassword:$('#current-password').value,password:$('#new-password').value})});csrf=result.csrf;$('#current-password').value='';$('#new-password').value='';$('#confirm-password').value='';$('#password-error').textContent='';toast('Password changed. Other sessions were signed out.')}catch(err){$('#password-error').textContent=err.message}finally{b.disabled=false}};
 if(currentUser?.role==='owner')$('#manage-users').onclick=manageUsers;
 $('#refresh-library').onclick=async()=>{try{if(saving)return;await loadRemote();toast('Latest server library loaded.')}catch(err){toast(err.message)}};
 $('#json-export').onclick=()=>download('folio-library.json',JSON.stringify({version:1,papers,exported:new Date().toISOString()},null,2),'application/json');
 $('#json-import').onclick=()=>$('#json-file').click();
 $('#json-file').onchange=async e=>{try{if(saving)return;const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw new Error('Library JSON must be smaller than 10 MB.');mergeBackup(JSON.parse(await file.text()));await save();render();toast('Library imported to server.')}catch(err){toast(err.message)}};
 $('#logout').onclick=async()=>{try{if(saving)return;await remoteApi('/api/logout',{method:'POST',body:'{}'});showLogin()}catch(err){toast(err.message)}};
}

function renderPhoneLibrary(){
 const unread=papers.filter(p=>p.status==='unread').length;
 const read=papers.filter(p=>p.status==='read').length;
 const title=collectionLabel()||(view==='queue'?'Your next read.':view==='favorites'?'Worth keeping close.':'Your reading shelf.');
 $('#main').innerHTML=`<div class="phone-heading"><div><div class="eyebrow">A LITTLE SPACE FOR BIG IDEAS</div><h1>${esc(title)}</h1><p>${view==='queue'?'One paper. A new perspective.':view==='favorites'?'The ideas you want to come back to.':`${papers.length} collected · ${read} read`}</p></div><button class="phone-add" id="add-paper" aria-label="Add paper">${icon('plus')}</button></div>
 <section class="phone-next"><div class="phone-next-top"><span>${icon('book')} ${unread} waiting to be read</span><span aria-hidden="true">✦</span></div><h2>${unread?'Make time for one good idea.':'Ready for something new?'}</h2><button class="button primary" id="pick-paper">${unread?'Pick my next read':'Discover papers'}${icon('arrow')}</button>${view==='queue'?'<div class="queue-options"><label><input id="prefer-important" type="checkbox" checked> Important first</label><label><input id="random-pick" type="checkbox"> Random pick</label></div>':''}</section>
 <div class="phone-section"><h2>${collection?'In this collection':view==='queue'?'Unread papers':view==='favorites'?'Important papers':'Your papers'} <span id="result-count" aria-live="polite"></span></h2></div>
 <label class="search phone-search">${icon('search')}<input id="search" type="search" placeholder="Search your papers…" aria-label="Search papers" value="${esc(query)}"></label>
 <details class="phone-filters" ${collection||statusFilter!=='all'||priorityFilter!=='all'||sort!=='newest'?'open':''}><summary>${icon('list')}Filter & sort</summary><div class="phone-filter-fields"><div class="phone-collection-field"><span>Collections</span>${collectionFilterButton()}</div><label>Reading status<select id="status-filter"><option value="all">All statuses</option><option value="unread">Unread</option><option value="reading">Reading</option><option value="read">Read</option></select></label><label>Importance<select id="priority-filter"><option value="all">All importance</option>${importanceOptions()}</select></label><label>Sort by<select id="sort"><option value="newest">Newest added</option><option value="oldest">Oldest added</option><option value="year">Publication year</option><option value="title">Title A–Z</option><option value="importance">Importance</option></select></label></div></details>
 <div class="paper-grid phone-papers" id="paper-results"></div>${papers.some(p=>p.sample)?'<div class="sample-note"><span>Sample library</span><button id="remove-samples">Remove samples</button></div>':''}`;
 renderPapers();
 $('#status-filter').value=statusFilter;$('#priority-filter').value=priorityFilter;$('#sort').value=sort;
 $('#search').oninput=e=>{query=e.target.value;renderPapers()};
 $('#status-filter').onchange=e=>{statusFilter=e.target.value;renderPapers()};
 $('#priority-filter').onchange=e=>{priorityFilter=e.target.value;renderPapers()};
 $('#sort').onchange=e=>{sort=e.target.value;renderPapers()};
}
phoneMedia?.addEventListener('change',()=>render());
